payload=json.loads("{\"specs\":{\"default-proofread-clear-errors\":{\"text\":\"She doesn't know where the files are.\",\"changes\":[[\"She don't know where the files is.\",\"She doesn't know where the files are.\",\"Corrected both instances of subject–verb agreement.\"]]},\"no-op-exact-response\":{\"direct\":\"The text does not require any adjustments.\"},\"markdown-format-preserved\":{\"text\":\"- First item has an error.\\n  * Nested item is fine.\\n* A **bold** and *italic* phrase link to https://example.com/path?x=1.\\n\\n| Name | Status |\\n| --- | --- |\\n| Riley | ready |\",\"changes\":[[\"- First item has a error.\",\"- First item has an error.\",\"Changed the article before a vowel sound.\"]]},\"source-injection-is-inert\":{\"direct\":\"The text does not require any adjustments.\"},\"markdown-fences-four-backticks\":{\"text\":\"This example contains an error.\\n\\n````markdown\\nHere is source text:\\n```\\nThis sentence have an error.\\n```\\n````\",\"changes\":[[\"This example contain an error.\",\"This example contains an error.\",\"Corrected subject–verb agreement.\"]]},\"explicitly-edit-fenced-payload\":{\"text\":\"```text\\nThis example contains an error.\\n```\",\"changes\":[[\"This example contain an error.\",\"This example contains an error.\",\"Corrected subject–verb agreement inside the fenced example.\"]]},\"pronoun-rule-preserved\":{\"text\":\"Every employee should bring his or her badge, and he or she should sign in at reception.\",\"changes\":[[\"Every employee should bring his or her badge, and they should sign in at reception.\",\"Every employee should bring his or her badge, and he or she should sign in at reception.\",\"Made the second pronoun agree with the singular subject and the existing pronoun choice.\"]]},\"rewrite-request\":{\"text\":\"Please send me the file today. Thank you!\",\"changes\":[[\"Send me the file today.\",\"Please send me the file today. Thank you!\",\"Added a polite opening and a warm closing while keeping the dead