cters-in-changes\":{\"text\":\"Please check the **draft** marked <ready>, &copy;, and ~~pending~~ today.\",\"changes\":[[\"Check the **draft** marked <ready>, &copy;, and ~~pending~~ today.\",\"Please check the **draft** marked <ready>, &copy;, and ~~pending~~ today.\",\"Added a polite opening while preserving the markup and deadline.\"]]},\"rewrite-autolink-punctuation-in-changes\":{\"text\":\"Please check https://example.com/a?x=1&y=2 and www.example.com/a_b, then email user@example.com today.\",\"changes\":[[\"Check https://example.com/a?x=1&y=2 and www.example.com/a_b, then email user@example.com today.\",\"Please check https://example.com/a?x=1&y=2 and www.example.com/a_b, then email user@example.com today.\",\"Added a polite opening while preserving both URLs, the email address, and the deadline.\"]]},\"fragment-labels-no-op\":{\"direct\":\"The text does not require any adjustments.\"},\"finite-clause-agreement\":{\"text\":\"- The **bold** and *italic* phrase links readers to https://example.com/path?x=1.\\n- The summary is helpful.\",\"changes\":[[\"- The **bold** and *italic* phrase link readers to https://example.com/path?x=1.\",\"- The **bold** and *italic* phrase links readers to https://example.com/path?x=1.\",\"Made the verb agree with the singular subject.\"]]},\"fragment-labels-article-only\":{\"text\":\"- A **bold** and *italic* phrase link to https://example.com/path?x=1.\\n- An unusual report summary.\",\"changes\":[[\"- A unusual report summary.\",\"- An unusual report summary.\",\"Changed the article before a vowel sound while preserving the noun-phrase label.\"]]},\"trim-the-fat\":{\"text\":\"Due to the fact that we were late, we made the decision to reschedule the meeting for a later time.\",\"changes\":[[\"Due to the fact that we were late, we decided to make the decision to reschedule the meeting for a later time.\",\"Due to the fact that we were late, we made the decision to reschedule the meeting for a later time.\",\"Removed redundant decision wording while preserving the reason and the decision to reschedule.\"]]},\"less-wordy\":{\"text\":\"At this point, we are reviewing the proposal, and we will provide a response at a later date.\",\"changes\":[[\"At this point in time, we are currently in the process of reviewing the proposal, and we will provide a response at a later date.\",\"At this point, we are reviewing the proposal, and we will provide a response at a later date.\",\"Shortened the introductory time phrase and simplified the description of the ongoing review while preserving the later response.\"]]},\"more-concise\":{\"text\":\"We have received your request and will respond to you as soon as we are able.\",\"changes\":[[\"We have received your request, and we want to let you know that we will respond to you as soon as we are able to do so.\",\"We have received your request and will respond to you as soon as we are able.\",\"Removed the redundant announcement and simplified the closing phrase while preserving receipt of the request and the commitment to respond when able.\"]]},\"more-succinct\":{\"text\":\"If weather is poor, we may need to decide whether to postpone the event.\",\"changes\":[[\"In the event that the weather conditions are poor, we may need to make a decision about whether or not to postpone the event until a later date.\",\"If weather is poor, we may need to decide whether to postpone the event.\",\"Shortened the condition and decision wording while preserving uncertainty and the need to decide whether to postpone.\"]]},\"shorten-markdown-changes-quotes\":{\"text\":\"We are in the process of reviewing the **draft** in `C:\\\\reports` and the [notes](https://example.com/notes) and will decide whether to send them later.\",\"changes\":[[\"At this point in time, we are currently in the process of reviewing the **draft** in `C:\\\\reports` and the [notes](https://example.com/notes), and we will make a decision about whether to send them later.\",\"We are in the process of reviewing the **draft** in `C:\\\\reports` and the [notes](https://example.com/notes) and will decide whether to send them later.\",\"Removed redundant time and review wording and simplified the decision phrase while preserving the Markdown, path, link, and decision about whether to send the items later.\"]]}},\"shortening\":[{\"id\":\"trim-the-fat\",\"text\":\"Due to the fact that we were late, we made the decision to reschedule the meeting for a later time.\",\"original_words\":22,\"final_words\":20,\"reduction\":0.09090909090909091,\"budget_min\":20,\"budget_max\":21,\"within_budget\":true},{\"id\":\"less-wordy\",\"text\":\"At this point, we are reviewing the proposal, and we will provide a response at a later date.\",\"original_words\":25,\"final_words\":18,\"reduction\":0.28,\"budget_min\":18,\"budget_max\":18,\"within_budget\":true},{\"id\":\"more-concise\",\"text\":\"We have received your request and will respond to you as soon as we are able.\",\"original_words\":27,\"final_words\":16,\"reduction\":0.4074074074074074,\"budget_min\":16,\"budget_max\":16,\"within_budget\":true},{\"id\":\"more-succinct\",\"text\":\"If weather is poor, we may need to decide whether to postpone the event.\",\"original_words\":28,\"final_words\":14,\"reduction\":0.5,\"budget_min\":11,\"budget_max\":14,\"within_budget\":true},{\"id\":\"shorten-markdown-changes-quotes\",\"text\":\"We are in the process of reviewing the **draft** in `C:\\\\reports` and the [notes](https://example.com/notes) and will decide whether to send them later.\",\"original_words\":32,\"final_words\":22,\"reduction\":0.3125,\"budget_min\":22,\"budget_max\":22,\"within_budget\":true}]}")
with open('envelope.json') as f:
    envelope=json.load(f)
specs=payload['specs']
def quoted(s):
    return '**"' + ''.join('\\'+ch if ch in string.punctuation else ch for ch in s) + '"**'
def inline(s):
    out=[]; i=0
    while i<len(s):
        if s[i]=='\\' and i+1<len(s) and s[i+1] in string.punctuation:
            out.append(html.escape(s[i+1])); i+=2
        elif s.startswith('**',i):
            end=s.find('**',i+2)
            assert end>=0
            out.append('<strong>'+inline(s[i+2:end])+'</strong>'); i=end+2
        elif s[i]=='`':
            end=s.find('`',i+1); assert end>=0
            out.append('<code>'+html.escape(s[i+1:end])+'</code>'); i=end+1
        else:
            out.append(html.escape(s[i])); i+=1
    return ''.join(out)
def render(md):
    lines=md.splitlines(); out=[]; i=0
    while i<len(lines):
        line=lines[i]
        m=re.fullmatch(r'(`{3,})text',line)
        if m:
            mark=m.group(1); i+=1; content=[]
            while i<len(lines) and lines[i]!=mark:
                content.append(lines[i]); i+=1
            assert i<len(lines)
            out.append('<pre><code class="language-text">'+html.escape('\n'.join(content))+'\n</code></pre>'); i+=1
        elif line.startswith('- '):
            items=[]
            while i<len(lines) and lines[i].startswith('- '):
                items.append('<li>'+inline(lines[i][2:])+'</li>'); i+=1
            out.append('<ul>'+''.join(items)+'</ul>')
        elif not line:
            i+=1
        else:
            paragraph=[line]; i+=1
            while i<len(lines) and lines[i] and not lines[i].startswith('- '):
                paragraph.append(lines[i]); i+=1
            out.append('<p>'+inline('\n'.join(paragraph))+'</p>')
    return '\n'.join(out)
responses=[]; measurements=[]; renders=[]
for c in envelope['cases']:
    cid=c['id']; spec=specs[cid]
    p=c['prompt'][len(envelope['runner_context']):].lstrip('\n')
    if 'direct' in spec:
        response=spec['direct']
        measurements.append({'id':cid,'block_required':False})
    else:
        t=spec['text']
        longest=max((len(run) for run in re.findall(r'`+',t)),default=0)
        k=max(3,longest+1); marker='`'*k
        response=marker+'text\n'+t+'\n'+marker
        source=None
        if not spec.get('draft'):
            if 'Source:\n' in p:
                source=p.split('Source:\n',1)[1]
            elif cid in ('markdown-format-preserved','markdown-fences-four-backticks'):
                source=p.split('Proofread:\n',1)[1]
            elif cid=='explicitly-edit-fenced-payload':
                source=p.split('\n\n',1)[1]
            elif cid in ('finite-clause-agreement','fragment-labels-article-only'):
                source=p.split(':\n',1)[1]
            elif cid=='implicit-proofreading-activation':
                source=p.split('Can you clean this up for me? ',1)[1]
            else:
                source=p.split(': ',1)[1]
            edited=source
            items=[]
            for before,after,explanation in spec['changes']:
                assert before in edited,(cid,before)
                assert before!=after
                edited=edited.replace(before,after,1)
                assert '"' not in explanation and "'" not in explanation
                items.append('- '+quoted(before)+' → '+quoted(after)+': '+explanation)
            assert edited==t,(cid,edited,t)
            response+='\n\nChanges:\n'+'\n'.join(items)
        assert response.startswith(marker+'text\n')
        assert response.splitlines()[len(t.splitlines())+1]==marker
        if cid=='markdown-fences-four-backticks':
            assert source.split('\n\n',1)[1]==t.split('\n\n',1)[1]
        if cid=='explicitly-edit-fenced-payload':
            assert source.splitlines()[0]==t.splitlines()[0]
            assert source.splitlines()[-1]==t.splitlines()[-1]
        if spec.get('draft'):
            assert len(re.findall(r'[.!?](?:\s|$)',t))==2
        measurements.append({'id':cid,'block_required':True,'final_text':t,'longest_backtick_run':longest,'fence_length':k,'matching_fences':True,'complete_changes_reconstruct_result':source is not None,'edit_operations':None if source is None else [dict(tag=tag,before=source[a:b],after=t[x:y]) for tag,a,b,x,y in difflib.SequenceMatcher(None,source,t).get_opcodes() if tag!='equal']})
    rendered=render(response)
    for before,after,_ in spec.get('changes',[]):
        for span in (before,after):
            expected='<strong>'+html.escape('"'+span+'"')+'</strong>'
            assert expected in rendered,(cid,span)
    responses.append({'id':cid,'response':response})
    renders.append({'id':cid,'html':rendered})
assert len(responses)==len(envelope['cases'])
assert {r['id'] for r in responses}=={c['id'] for c in envelope['cases']}
for row in payload['shortening']:
    assert specs[row['id']]['text']==row['text']
print(json.dumps({'responses':responses,'checks':measurements,'shortening':payload['shortening'],'renderer_evidence':{'renderer':'Local renderer for the Markdown subset emitted here: fenced text blocks, paragraphs, lists, strong emphasis, inline code, and backslash escapes. No host UI acceptance is implied.','results':renders}},ensure_ascii=False))
